import {direction,pointAngles} from './tour-spatial.js';
export async function mountPanorama(stage,url,host,options={}){
 const T=await import('./vendor/three/three.module.js'),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.domElement.style.cssText='width:100%;height:100%;display:block;touch-action:none';stage.append(renderer.domElement);
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(75,1,.1,100),geometry=new T.SphereGeometry(10,48,24);geometry.scale(-1,1,1);let texture;
 try{texture=await new T.TextureLoader().loadAsync(url);}catch(e){renderer.dispose();geometry.dispose();renderer.domElement.remove();throw e;}
 if(!stage.isConnected||stage.closest('dialog')&&!stage.closest('dialog').open){texture.dispose();geometry.dispose();renderer.dispose();renderer.domElement.remove();throw Error('Vista cerrada');}
 texture.colorSpace=T.SRGBColorSpace;const material=new T.MeshBasicMaterial({map:texture});scene.add(new T.Mesh(geometry,material));let yaw=options.yaw??-Math.PI/2,pitch=options.pitch??0,dead=false;const pointers=new Map();let pinch=null;
 const overlay=document.createElement('div');overlay.className='tour-scene-links';const points=(options.points||[]).map(p=>{const b=document.createElement('button');b.type='button';b.className='tour-point';b.textContent=p.label;b.setAttribute('aria-label','Ir a '+p.label);b.onclick=()=>options.navigate(p.target);overlay.append(b);return{button:b,...pointAngles(p)};});stage.append(overlay);
 const draw=()=>{if(dead)return;const {width,height}=stage.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();pitch=Math.max(-1.4,Math.min(1.4,pitch));const aim=direction(yaw,pitch);camera.lookAt(aim.x,aim.y,aim.z);camera.updateMatrixWorld();renderer.render(scene,camera);
  const forward=camera.getWorldDirection(new T.Vector3());for(const p of points){const d=direction(p.yaw,p.pitch),v=new T.Vector3(d.x,d.y,d.z);const front=forward.dot(v)>0;v.project(camera);p.button.hidden=!front||Math.abs(v.x)>.93||Math.abs(v.y)>.9;p.button.style.left=(v.x*.5+.5)*width+'px';p.button.style.top=(-v.y*.5+.5)*height+'px';}
 };
 const canvas=renderer.domElement,down=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);pinch=null;},move=e=>{const p=pointers.get(e.pointerId);if(!p)return;const old={...p};p.x=e.clientX;p.y=e.clientY;if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(pinch&&distance>1)camera.fov=Math.max(35,Math.min(100,camera.fov*pinch/distance));pinch=distance;}else{yaw-=(p.x-old.x)*.005;pitch+=(p.y-old.y)*.005;}draw();},up=e=>{pointers.delete(e.pointerId);pinch=null;},zoom=e=>{camera.fov=Math.max(35,Math.min(100,75/e.detail));draw();},look=e=>{yaw+=e.detail;draw();},wheel=e=>{e.preventDefault();camera.fov=Math.max(35,Math.min(100,camera.fov+Math.sign(e.deltaY)*3));draw();};
 canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up);canvas.addEventListener('lostpointercapture',up);canvas.addEventListener('wheel',wheel,{passive:false});host.addEventListener('tour-look',look);host.addEventListener('tour-zoom',zoom);
 const size=new ResizeObserver(draw);size.observe(stage);const dialog=host.closest('dialog');const dispose=()=>{if(dead)return;dead=true;size.disconnect();mutation.disconnect();host.removeEventListener('tour-zoom',zoom);host.removeEventListener('tour-look',look);dialog?.removeEventListener('close',dispose);texture.dispose();geometry.dispose();material.dispose();renderer.dispose();canvas.remove();overlay.remove();};const mutation=new MutationObserver(()=>{if(!host.isConnected||!stage.isConnected)dispose();});mutation.observe(document.body,{childList:true,subtree:true});dialog?.addEventListener('close',dispose,{once:true});draw();return dispose;
}
